using System.Diagnostics;
using System.Net;
using System.Text;
using MelodyBridge.Core;
using MelodyBridge.Infrastructure.Audio;
using MelodyBridge.Infrastructure.Rhythmax;
using Microsoft.Extensions.Logging.Abstractions;

namespace MelodyBridge.Tests.Infrastructure;

/// <summary>
/// The Rhythmax production download path without the public account pool:
/// a scripted token, manifest and DASH response, real fragmented MP4 audio
/// generated by ffmpeg, and the actual remux / file naming. This is the
/// fast counterpart to the live tests that can skip when the public pool
/// has no playback slot.
/// </summary>
[TestFixture]
public class RhythmaxDownloadTests
{
    private readonly List<string> _tempDirs = new();

    [TearDown]
    public void TearDown()
    {
        foreach (var dir in _tempDirs)
            try { Directory.Delete(dir, recursive: true); } catch { /* best effort */ }
        _tempDirs.Clear();
    }

    private string NewDir()
    {
        var dir = Path.Combine(Path.GetTempPath(), $"mb-rhythmax-{Guid.NewGuid():N}");
        Directory.CreateDirectory(dir);
        _tempDirs.Add(dir);
        return dir;
    }

    private sealed class ScriptedHandler : HttpMessageHandler
    {
        public List<(string Url, string? Authorization)> Requests { get; } = new();
        public Func<HttpRequestMessage, HttpResponseMessage> Respond { get; set; } =
            _ => new HttpResponseMessage(HttpStatusCode.NotFound);

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken ct)
        {
            Requests.Add((request.RequestUri!.AbsoluteUri,
                request.Headers.Authorization?.Parameter));
            return Task.FromResult(Respond(request));
        }
    }

    private static HttpResponseMessage Json(string body, HttpStatusCode status = HttpStatusCode.OK)
        => new(status) { Content = new StringContent(body, Encoding.UTF8, "application/json") };

    private static HttpResponseMessage Bytes(byte[] data)
        => new(HttpStatusCode.OK) { Content = new ByteArrayContent(data) };

    private static RhythmaxClient Client(ScriptedHandler handler)
        => new(new HttpClient(handler), "https://hifi.test",
            NullLogger<RhythmaxClient>.Instance);

    private static RhythmaxDownloader Downloader(ScriptedHandler handler)
    {
        var config = new StubPluginConfig();
        config.Set("rhythmax", "base_url", "https://hifi.test");
        return new RhythmaxDownloader(Client(handler), config,
            NullLogger<RhythmaxDownloader>.Instance);
    }

    private static string ManifestJson(string uri = "https://hifi.test/track.mpd")
        => """
        {"data":{"id":"35986110","type":"trackManifests","attributes":{
          "trackPresentation":"FULL","uri":"__URI__","formats":["FLAC"]}}}
        """.Replace("__URI__", uri);

    private static string DashXml(string codec)
        => """
        <?xml version="1.0" encoding="UTF-8"?>
        <MPD xmlns="urn:mpeg:dash:schema:mpd:2011" type="static">
          <Period id="0"><AdaptationSet contentType="audio" mimeType="audio/mp4">
            <Representation id="0" codecs="__CODEC__" bandwidth="900000">
              <SegmentTemplate timescale="44100"
                initialization="https://hifi.test/init"
                media="https://hifi.test/seg" startNumber="1">
                <SegmentTimeline><S d="44100"/></SegmentTimeline>
              </SegmentTemplate>
            </Representation>
          </AdaptationSet></Period>
        </MPD>
        """.Replace("__CODEC__", codec);

    /// <summary>
    /// A one second fragmented MP4 containing real audio. The downloader
    /// concatenates init and media segments; serving the whole file as the
    /// init and an empty segment exercises the same concat and remux path.
    /// </summary>
    private static byte[] FragmentedMp4(string codec)
    {
        var ffmpeg = SpectrumAnalyzer.FindBinary("ffmpeg");
        if (ffmpeg is null) Assert.Ignore("ffmpeg is required for the fragmented MP4 fixture");
        var path = Path.Combine(Path.GetTempPath(), $"mb-rhythmax-{Guid.NewGuid():N}.mp4");
        try
        {
            var info = new ProcessStartInfo(ffmpeg)
            {
                RedirectStandardError = true,
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true,
            };
            foreach (var arg in new[]
                     {
                         "-y", "-v", "error", "-f", "lavfi", "-i",
                         "sine=frequency=440:duration=1", "-c:a", codec,
                         "-f", "mp4", "-movflags",
                         "frag_keyframe+empty_moov+default_base_moof", path,
                     })
                info.ArgumentList.Add(arg);
            using var process = Process.Start(info)!;
            process.WaitForExit(30000);
            Assert.That(process.ExitCode, Is.Zero, "the fragmented MP4 fixture did not encode");
            return File.ReadAllBytes(path);
        }
        finally
        {
            try { File.Delete(path); } catch { /* best effort */ }
        }
    }

    [Test]
    public async Task Download_Lossless_RemuxesTheDashStreamToFlac()
    {
        var payload = FragmentedMp4("flac");
        using var handler = new ScriptedHandler();
        handler.Respond = request => request.RequestUri!.AbsoluteUri switch
        {
            "https://hifi.test/token" => Json("""{"access_token":"play-token","expires_in":600}"""),
            var url when url.Contains("/manifests") => Json(ManifestJson()),
            "https://hifi.test/track.mpd" => new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent(DashXml("flac"), Encoding.UTF8, "application/dash+xml"),
            },
            "https://hifi.test/init" => Bytes(payload),
            "https://hifi.test/seg" => Bytes(Array.Empty<byte>()),
            _ => new HttpResponseMessage(HttpStatusCode.NotFound),
        };

        var result = await Downloader(handler).DownloadAsync(
            "https://tidal.com/browse/track/35986110", NewDir(), "mb-rhythmax-flac",
            new DownloadQuality(AudioFormat.Flac));

        Assert.That(result.Success, Is.True, result.ErrorMessage);
        Assert.That(AudioSignature.DetectContainer(result.FilePath!), Is.EqualTo(".flac"));
        Assert.That(handler.Requests.Any(r => r.Url.Contains("/manifests") && r.Url.Contains("quality=LOSSLESS")),
            Is.True);
        Assert.That(handler.Requests.Any(r => r.Url == "https://hifi.test/init"), Is.True);
        Assert.That(handler.Requests.Any(r => r.Url == "https://hifi.test/seg"), Is.True);
    }

    [Test]
    public async Task Download_High_PicksTheAacRepresentationAndKeepsM4a()
    {
        var payload = FragmentedMp4("aac");
        using var handler = new ScriptedHandler();
        handler.Respond = request => request.RequestUri!.AbsoluteUri switch
        {
            "https://hifi.test/token" => Json("""{"access_token":"play-token","expires_in":600}"""),
            var url when url.Contains("/manifests") => Json(ManifestJson()),
            "https://hifi.test/track.mpd" => new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent(DashXml("mp4a.40.2"), Encoding.UTF8, "application/dash+xml"),
            },
            "https://hifi.test/init" => Bytes(payload),
            "https://hifi.test/seg" => Bytes(Array.Empty<byte>()),
            _ => new HttpResponseMessage(HttpStatusCode.NotFound),
        };

        var result = await Downloader(handler).DownloadAsync(
            "https://tidal.com/browse/track/35986110", NewDir(), "mb-rhythmax-aac",
            new DownloadQuality(AudioFormat.Aac, null, 320));

        Assert.That(result.Success, Is.True, result.ErrorMessage);
        Assert.That(AudioSignature.DetectContainer(result.FilePath!), Is.EqualTo(".m4a"));
        Assert.That(handler.Requests.Any(r => r.Url.Contains("/manifests") && r.Url.Contains("quality=HIGH")),
            Is.True);
    }

    [Test]
    public async Task Download_FailedSegment_CleansUpAndReturnsTheError()
    {
        var dir = NewDir();
        using var handler = new ScriptedHandler();
        handler.Respond = request => request.RequestUri!.AbsoluteUri switch
        {
            "https://hifi.test/token" => Json("""{"access_token":"play-token","expires_in":600}"""),
            var url when url.Contains("/manifests") => Json(ManifestJson()),
            "https://hifi.test/track.mpd" => new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent(DashXml("flac"), Encoding.UTF8, "application/dash+xml"),
            },
            "https://hifi.test/init" => Bytes(FragmentedMp4("flac")),
            "https://hifi.test/seg" => new HttpResponseMessage(HttpStatusCode.NotFound),
            _ => new HttpResponseMessage(HttpStatusCode.NotFound),
        };

        var result = await Downloader(handler).DownloadAsync(
            "https://tidal.com/browse/track/35986110", dir, "mb-rhythmax-fail",
            new DownloadQuality(AudioFormat.Flac));

        Assert.That(result.Success, Is.False);
        Assert.That(result.ErrorMessage, Is.Not.Null.And.Not.Empty);
        Assert.That(Directory.EnumerateFiles(dir, ".mb-rhythmax-*").Any(), Is.False,
            "a failed download must not leave its work file behind");
        Assert.That(Directory.EnumerateFiles(dir, "tidal-*").Any(), Is.False);
    }
}
